export default {
  preset: 'ts-jest',
  testEnvironment: 'node',
  roots: ['<rootDir>/tests', '<rootDir>/src'],
  testMatch: ['**/__tests__/**/*.ts', '**/?(*.)+(spec|test).ts'],
  moduleFileExtensions: ['ts', 'tsx', 'js', 'jsx', 'json', 'node'],
  collectCoverageFrom: [
    'src/**/*.ts',
    '!src/**/*.d.ts',
  ],
};

export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[];
  [key: string]: unknown;
}

export interface ParsedMarkdown {
  frontmatter: Frontmatter;
  content: string;
  html: string;
}

export interface PageMetadata {
  filename: string;
  title: string;
  date?: string;
  tags: string[];
  url: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

import { marked } from 'marked';
import matter from 'gray-matter';
import { Frontmatter, ParsedMarkdown } from './types.js';

function parseYamlFrontmatter(yamlString: string): Frontmatter {
  const frontmatter: Frontmatter = {};

  const lines = yamlString.split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const colonIndex = trimmed.indexOf(':');
    if (colonIndex === -1) continue;

    const key = trimmed.substring(0, colonIndex).trim();
    const value = trimmed.substring(colonIndex + 1).trim();

    if (key === 'tags') {
      frontmatter.tags = value
        .split(',')
        .map((tag) => tag.trim())
        .filter((tag) => tag.length > 0);
    } else if (key === 'title' || key === 'date') {
      frontmatter[key] = value.replace(/^["']|["']$/g, '');
    } else {
      frontmatter[key] = value;
    }
  }

  return frontmatter;
}

export function parseMarkdown(content: string): ParsedMarkdown {
  const matterResult = matter(content);
  const rawFrontmatter = matterResult.data as Frontmatter;

  // If matterResult has content in the frontmatter (YAML block), parse it
  let frontmatter = rawFrontmatter;
  if (matterResult.content.startsWith('---')) {
    const match = matterResult.content.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
    if (match) {
      const yamlBlock = match[1];
      frontmatter = parseYamlFrontmatter(yamlBlock);
      return {
        frontmatter,
        content: match[2],
        html: marked(match[2]),
      };
    }
  }

  return {
    frontmatter,
    content: matterResult.content,
    html: marked(matterResult.content),
  };
}

import * as fs from 'fs';
import * as path from 'path';
import { parseMarkdown } from './parser.js';
import { BuildOptions, PageMetadata } from './types.js';

export class SiteGenerator {
  private contentDir: string;
  private outputDir: string;

  constructor(options: BuildOptions) {
    this.contentDir = options.contentDir;
    this.outputDir = options.outputDir;
  }

  private ensureDir(dirPath: string): void {
    if (!fs.existsSync(dirPath)) {
      fs.mkdirSync(dirPath, { recursive: true });
    }
  }

  private getMarkdownFiles(): string[] {
    if (!fs.existsSync(this.contentDir)) {
      return [];
    }

    return fs
      .readdirSync(this.contentDir)
      .filter((file) => file.endsWith('.md'))
      .sort();
  }

  private generatePageHtml(title: string, content: string): string {
    return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${this.escapeHtml(title)}</title>
  <style>
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
      line-height: 1.6;
      max-width: 800px;
      margin: 0 auto;
      padding: 20px;
      color: #333;
    }
    h1, h2, h3, h4, h5, h6 { margin-top: 1.5em; }
    code {
      background: #f0f0f0;
      padding: 2px 6px;
      border-radius: 3px;
      font-family: 'Courier New', monospace;
    }
    pre {
      background: #f5f5f5;
      padding: 10px;
      border-radius: 5px;
      overflow-x: auto;
    }
    pre code { background: none; padding: 0; }
    a { color: #0066cc; text-decoration: none; }
    a:hover { text-decoration: underline; }
    .nav { margin-bottom: 20px; }
    .nav a { margin-right: 15px; }
  </style>
</head>
<body>
  <div class="nav">
    <a href="index.html">← Home</a>
  </div>
  <h1>${this.escapeHtml(title)}</h1>
  <div>${content}</div>
</body>
</html>`;
  }

  private generateIndexHtml(pages: PageMetadata[]): string {
    const pagesList = pages
      .map(
        (page) => `    <li>
      <a href="${this.escapeHtml(page.url)}">${this.escapeHtml(page.title)}</a>
      ${page.date ? `<span style="color: #666; margin-left: 10px;">${this.escapeHtml(page.date)}</span>` : ''}
      ${page.tags.length > 0 ? `<div style="margin-top: 5px;"><small>${page.tags.map((tag) => `<span style="display: inline-block; background: #eee; padding: 2px 8px; border-radius: 3px; margin-right: 5px;">${this.escapeHtml(tag)}</span>`).join('')}</small></div>` : ''}
    </li>`
      )
      .join('\n');

    return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Static Site</title>
  <style>
    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
      line-height: 1.6;
      max-width: 800px;
      margin: 0 auto;
      padding: 20px;
      color: #333;
    }
    h1 { margin-top: 0; }
    ul { list-style: none; padding: 0; }
    li {
      padding: 15px;
      border: 1px solid #eee;
      margin-bottom: 10px;
      border-radius: 5px;
    }
    li:hover { background: #f9f9f9; }
    a { color: #0066cc; text-decoration: none; }
    a:hover { text-decoration: underline; }
  </style>
</head>
<body>
  <h1>Pages</h1>
  ${pages.length > 0 ? `<ul>\n${pagesList}\n  </ul>` : '<p>No pages found.</p>'}
</body>
</html>`;
  }

  private escapeHtml(text: string): string {
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  async build(): Promise<void> {
    this.ensureDir(this.outputDir);

    const markdownFiles = this.getMarkdownFiles();
    const pages: PageMetadata[] = [];

    for (const file of markdownFiles) {
      const filePath = path.join(this.contentDir, file);
      const content = fs.readFileSync(filePath, 'utf-8');
      const parsed = parseMarkdown(content);

      const title = parsed.frontmatter.title || file.replace('.md', '');
      const slug = file.replace('.md', '.html');
      const outputPath = path.join(this.outputDir, slug);

      fs.writeFileSync(outputPath, this.generatePageHtml(title, parsed.html));

      pages.push({
        filename: file,
        title,
        date: parsed.frontmatter.date ? String(parsed.frontmatter.date) : undefined,
        tags: Array.isArray(parsed.frontmatter.tags)
          ? parsed.frontmatter.tags.map((tag) => String(tag))
          : [],
        url: slug,
      });
    }

    const indexPath = path.join(this.outputDir, 'index.html');
    fs.writeFileSync(indexPath, this.generateIndexHtml(pages));

    console.log(`✓ Generated ${pages.length} page(s) to ${this.outputDir}`);
  }
}

#!/usr/bin/env node

import * as path from 'path';
import { SiteGenerator } from './generator.js';

function parseArgs(args: string[]): { command: string; contentDir: string; outputDir: string } {
  let command = 'build';
  let contentDir = './content';
  let outputDir = './dist';

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];

    if (!arg.startsWith('-')) {
      command = arg;
      continue;
    }

    if (arg === '--content' && i + 1 < args.length) {
      contentDir = args[++i];
    } else if (arg === '--output' && i + 1 < args.length) {
      outputDir = args[++i];
    }
  }

  return { command, contentDir, outputDir };
}

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  const { command, contentDir, outputDir } = parseArgs(args);

  if (command !== 'build') {
    console.error(`Unknown command: ${command}`);
    process.exit(1);
  }

  const resolvedContentDir = path.resolve(contentDir);
  const resolvedOutputDir = path.resolve(outputDir);

  try {
    const generator = new SiteGenerator({
      contentDir: resolvedContentDir,
      outputDir: resolvedOutputDir,
    });

    await generator.build();
  } catch (error) {
    console.error('Error building site:', error instanceof Error ? error.message : String(error));
    process.exit(1);
  }
}

main();

import { parseMarkdown } from '../src/parser';

describe('Parser', () => {
  describe('parseMarkdown', () => {
    it('should parse markdown with YAML frontmatter', () => {
      const content = `---
title: Test Page
date: 2024-01-15
tags: typescript, cli
---

# Hello World

This is a test.`;

      const result = parseMarkdown(content);

      expect(result.frontmatter.title).toBe('Test Page');
      expect(result.frontmatter.date).toBe('2024-01-15');
      expect(result.frontmatter.tags).toEqual(['typescript', 'cli']);
      expect(result.content).toContain('# Hello World');
      expect(result.html).toContain('<h1>Hello World</h1>');
    });

    it('should handle markdown without frontmatter', () => {
      const content = '# Simple Page\n\nJust content.';

      const result = parseMarkdown(content);

      expect(result.frontmatter).toEqual({});
      expect(result.content).toContain('# Simple Page');
      expect(result.html).toContain('<h1>Simple Page</h1>');
    });

    it('should parse YAML with quoted values', () => {
      const content = `---
title: "My Special Page"
date: "2024-12-25"
---

Content here.`;

      const result = parseMarkdown(content);

      expect(result.frontmatter.title).toBe('My Special Page');
      expect(result.frontmatter.date).toBe('2024-12-25');
    });

    it('should handle multiple tags with whitespace', () => {
      const content = `---
title: Tagged Post
tags: python, javascript, rust, go
---

Content.`;

      const result = parseMarkdown(content);

      expect(result.frontmatter.tags).toEqual(['python', 'javascript', 'rust', 'go']);
    });

    it('should convert markdown to HTML', () => {
      const content = `---
title: Markdown Test
---

# Heading

**Bold text** and *italic text*

- Item 1
- Item 2

\`\`\`
code block
\`\`\``;

      const result = parseMarkdown(content);

      expect(result.html).toContain('<h1>Heading</h1>');
      expect(result.html).toContain('<strong>Bold text</strong>');
      expect(result.html).toContain('<em>italic text</em>');
      expect(result.html).toContain('<li>Item 1</li>');
      expect(result.html).toContain('<pre>');
      expect(result.html).toContain('<code>');
    });

    it('should handle empty tags', () => {
      const content = `---
title: No Tags
tags:
---

Content.`;

      const result = parseMarkdown(content);

      expect(result.frontmatter.tags).toEqual([]);
    });

    it('should preserve custom frontmatter fields', () => {
      const content = `---
title: Custom Fields
author: John Doe
category: tutorial
---

Content.`;

      const result = parseMarkdown(content);

      expect(result.frontmatter.title).toBe('Custom Fields');
      expect(result.frontmatter.author).toBe('John Doe');
      expect(result.frontmatter.category).toBe('tutorial');
    });
  });
});

import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import { SiteGenerator } from '../src/generator';

describe('SiteGenerator', () => {
  let tempDir: string;
  let contentDir: string;
  let outputDir: string;

  beforeEach(() => {
    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-test-'));
    contentDir = path.join(tempDir, 'content');
    outputDir = path.join(tempDir, 'dist');
    fs.mkdirSync(contentDir);
  });

  afterEach(() => {
    fs.rmSync(tempDir, { recursive: true, force: true });
  });

  it('should generate HTML files from markdown', async () => {
    const markdownContent = `---
title: Test Post
date: 2024-01-15
tags: test, markdown
---

# Test Post

This is a test post.`;

    fs.writeFileSync(path.join(contentDir, 'test.md'), markdownContent);

    const generator = new SiteGenerator({ contentDir, outputDir });
    await generator.build();

    const outputFile = path.join(outputDir, 'test.html');
    expect(fs.existsSync(outputFile)).toBe(true);

    const content = fs.readFileSync(outputFile, 'utf-8');
    expect(content).toContain('<title>Test Post</title>');
    expect(content).toContain('<h1>Test Post</h1>');
    expect(content).toContain('This is a test post.');
  });

  it('should generate index.html with all pages', async () => {
    fs.writeFileSync(
      path.join(contentDir, 'first.md'),
      `---
title: First Page
date: 2024-01-01
---

Content of first page.`
    );

    fs.writeFileSync(
      path.join(contentDir, 'second.md'),
      `---
title: Second Page
date: 2024-01-02
tags: important
---

Content of second page.`
    );

    const generator = new SiteGenerator({ contentDir, outputDir });
    await generator.build();

    const indexFile = path.join(outputDir, 'index.html');
    expect(fs.existsSync(indexFile)).toBe(true);

    const indexContent = fs.readFileSync(indexFile, 'utf-8');
    expect(indexContent).toContain('First Page');
    expect(indexContent).toContain('Second Page');
    expect(indexContent).toContain('first.html');
    expect(indexContent).toContain('second.html');
    expect(indexContent).toContain('2024-01-01');
    expect(indexContent).toContain('2024-01-02');
    expect(indexContent).toContain('important');
  });

  it('should handle markdown without frontmatter', async () => {
    const markdownContent = `# No Frontmatter

Just plain markdown.`;

    fs.writeFileSync(path.join(contentDir, 'plain.md'), markdownContent);

    const generator = new SiteGenerator({ contentDir, outputDir });
    await generator.build();

    const outputFile = path.join(outputDir, 'plain.html');
    expect(fs.existsSync(outputFile)).toBe(true);

    const content = fs.readFileSync(outputFile, 'utf-8');
    expect(content).toContain('<title>plain</title>');
  });

  it('should create output directory if it does not exist', async () => {
    fs.writeFileSync(
      path.join(contentDir, 'test.md'),
      `---
title: Test
---

Content.`
    );

    expect(fs.existsSync(outputDir)).toBe(false);

    const generator = new SiteGenerator({ contentDir, outputDir });
    await generator.build();

    expect(fs.existsSync(outputDir)).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'test.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
  });

  it('should handle empty content directory', async () => {
    const generator = new SiteGenerator({ contentDir, outputDir });
    await generator.build();

    expect(fs.existsSync(outputDir)).toBe(true);

    const indexFile = path.join(outputDir, 'index.html');
    expect(fs.existsSync(indexFile)).toBe(true);

    const indexContent = fs.readFileSync(indexFile, 'utf-8');
    expect(indexContent).toContain('No pages found');
  });

  it('should only process .md files', async () => {
    fs.writeFileSync(path.join(contentDir, 'markdown.md'), '# Markdown\n\nContent.');
    fs.writeFileSync(path.join(contentDir, 'text.txt'), 'This should not be processed.');
    fs.writeFileSync(path.join(contentDir, 'code.js'), 'console.log("ignored");');

    const generator = new SiteGenerator({ contentDir, outputDir });
    await generator.build();

    expect(fs.existsSync(path.join(outputDir, 'markdown.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'text.html'))).toBe(false);
    expect(fs.existsSync(path.join(outputDir, 'code.html'))).toBe(false);
  });

  it('should sort markdown files alphabetically', async () => {
    fs.writeFileSync(
      path.join(contentDir, 'zebra.md'),
      '---\ntitle: Zebra\n---\nZ'
    );
    fs.writeFileSync(
      path.join(contentDir, 'apple.md'),
      '---\ntitle: Apple\n---\nA'
    );
    fs.writeFileSync(
      path.join(contentDir, 'banana.md'),
      '---\ntitle: Banana\n---\nB'
    );

    const generator = new SiteGenerator({ contentDir, outputDir });
    await generator.build();

    const indexContent = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf-8');
    const applePos = indexContent.indexOf('Apple');
    const bananaPos = indexContent.indexOf('Banana');
    const zebraPos = indexContent.indexOf('Zebra');

    expect(applePos).toBeLessThan(bananaPos);
    expect(bananaPos).toBeLessThan(zebraPos);
  });

  it('should escape HTML in titles and content', async () => {
    const markdownContent = `---
title: <script>alert('xss')</script>
---

<img src=x onerror="alert('xss')">`;

    fs.writeFileSync(path.join(contentDir, 'xss.md'), markdownContent);

    const generator = new SiteGenerator({ contentDir, outputDir });
    await generator.build();

    const content = fs.readFileSync(path.join(outputDir, 'xss.html'), 'utf-8');
    expect(content).not.toContain('<script>');
    expect(content).not.toContain("alert('xss')");
    expect(content).toContain('&lt;');
    expect(content).toContain('&gt;');
  });

  it('should include navigation link to index from page', async () => {
    fs.writeFileSync(
      path.join(contentDir, 'page.md'),
      '---\ntitle: Page\n---\nContent.'
    );

    const generator = new SiteGenerator({ contentDir, outputDir });
    await generator.build();

    const content = fs.readFileSync(path.join(outputDir, 'page.html'), 'utf-8');
    expect(content).toContain('index.html');
    expect(content).toContain('← Home');
  });

  it('should display tags in index', async () => {
    fs.writeFileSync(
      path.join(contentDir, 'tagged.md'),
      '---\ntitle: Tagged Post\ntags: typescript, testing, cli\n---\nContent.'
    );

    const generator = new SiteGenerator({ contentDir, outputDir });
    await generator.build();

    const indexContent = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf-8');
    expect(indexContent).toContain('typescript');
    expect(indexContent).toContain('testing');
    expect(indexContent).toContain('cli');
  });
});

